3: /// 轻量极简 Markdown 视图：支持标题、列表、引用、分割线、GFM 表格与语法高亮代码块。
4: struct AgentMarkdownView: View {
5:     let text: String
6: 
7:     private var segments: [MarkdownSegment] {
8:         MarkdownSegment.parse(text)
9:     }
10: 
11:     var body: some View {
12:         VStack(alignment: .leading, spacing: 10) {
13:             ForEach(segments) { segment in
14:                 switch segment.kind {
15:                 case .prose(let content):
16:                     AgentProseBlockView(content: content)
17:                 case .code(let language, let code):
18:                     AgentCodeBlockView(language: language, code: code)
19:                 case .table(let headers, let alignments, let rows):
20:                     AgentMarkdownTableView(headers: headers, alignments: alignments, rows: rows)
21:                 case .blockquote(let content):
22:                     AgentBlockquoteView(content: content)
23:                 case .thematicBreak:
24:                     Rectangle()
25:                         .fill(Color(uiColor: .separator).opacity(0.35))
26:                         .frame(height: 0.5)
27:                         .padding(.vertical, 6)
28:                 }
29:             }
30:         }
31:         .frame(maxWidth: .infinity, alignment: .leading)
32:         .textSelection(.enabled)
33:     }
34: }
