36: private struct AgentProseBlockView: View {
37:     let content: String
38: 
39:     var body: some View {
40:         let lines = content.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
41:         VStack(alignment: .leading, spacing: 6) {
42:             ForEach(Array(lines.enumerated()), id: \.offset) { _, line in
43:                 proseLine(line)
44:             }
45:         }
46:     }
47: 
48:     @ViewBuilder
49:     private func proseLine(_ raw: String) -> some View {
50:         let leadingSpaces = raw.prefix(while: { $0 == " " || $0 == "\t" }).count
51:         let indent = CGFloat(min(leadingSpaces / 2, 4)) * 14
52:         let trimmed = raw.trimmingCharacters(in: .whitespaces)
53: 
54:         if trimmed.isEmpty {
55:             Spacer().frame(height: 2)
56:         } else if trimmed.hasPrefix("#### ") {
57:             AgentInlineMarkdownText(source: String(trimmed.dropFirst(5)))
58:                 .font(.subheadline.weight(.semibold))
59:                 .padding(.top, 4)
60:         } else if trimmed.hasPrefix("### ") {
61:             AgentInlineMarkdownText(source: String(trimmed.dropFirst(4)))
62:                 .font(.headline)
63:                 .padding(.top, 4)
64:         } else if trimmed.hasPrefix("## ") {
65:             AgentInlineMarkdownText(source: String(trimmed.dropFirst(3)))
66:                 .font(.title3.weight(.semibold))
67:                 .padding(.top, 6)
68:         } else if trimmed.hasPrefix("# ") {
69:             AgentInlineMarkdownText(source: String(trimmed.dropFirst(2)))
70:                 .font(.title2.weight(.bold))
71:                 .padding(.top, 6)
72:         } else if trimmed.hasPrefix("- ") || trimmed.hasPrefix("* ") {
73:             HStack(alignment: .top, spacing: 8) {
74:                 Text(indent > 0 ? "◦" : "•")
75:                     .foregroundStyle(.secondary)
76:                 AgentInlineMarkdownText(source: String(trimmed.dropFirst(2)))
77:             }
78:             .padding(.leading, 4 + indent)
79:         } else if let ordered = parseOrderedListLine(trimmed) {
80:             HStack(alignment: .top, spacing: 6) {
81:                 Text(verbatim: "\(ordered.number).")
82:                     .foregroundStyle(.secondary)
83:                 AgentInlineMarkdownText(source: ordered.body)
84:             }
85:             .padding(.leading, 4 + indent)
86:         } else {
87:             AgentInlineMarkdownText(source: raw)
88:         }
89:     }
90: 
91:     private func parseOrderedListLine(_ line: String) -> (number: String, body: String)? {
92:         guard let dotIndex = line.firstIndex(of: ".") else { return nil }
93:         let prefix = line[..<dotIndex]
94:         guard !prefix.isEmpty, prefix.allSatisfy(\.isNumber) else { return nil }
95:         let afterDot = line.index(after: dotIndex)
96:         guard afterDot < line.endIndex, line[afterDot] == " " else { return nil }
97:         let bodyStart = line.index(after: afterDot)
98:         return (String(prefix), String(line[bodyStart...]))
99:     }
100: }
