102: private struct AgentInlineMarkdownText: View {
103:     let source: String
104: 
105:     var body: some View {
106:         Text(Self.styledAttributedString(from: source))
107:     }
108: 
109:     private static func styledAttributedString(from source: String) -> AttributedString {
110:         guard var attributed = try? AttributedString(
111:             markdown: source,
112:             options: .init(interpretedSyntax: .inlineOnlyPreservingWhitespace)
113:         ) else {
114:             return AttributedString(source)
115:         }
116:         for run in attributed.runs {
117:             if let intent = run.inlinePresentationIntent, intent.contains(.code) {
118:                 attributed[run.range].font = .system(.subheadline, design: .monospaced)
119:                 attributed[run.range].backgroundColor = Color(uiColor: .tertiarySystemFill)
120:             }
121:         }
122:         return attributed
123:     }
124: }
