143: private struct AgentMarkdownTableView: View {
144:     let headers: [String]
145:     let alignments: [HorizontalAlignment]
146:     let rows: [[String]]
147: 
148:     var body: some View {
149:         ScrollView(.horizontal, showsIndicators: false) {
150:             Grid(alignment: .leading, horizontalSpacing: 0, verticalSpacing: 0) {
151:                 GridRow {
152:                     ForEach(Array(headers.enumerated()), id: \.offset) { col, header in
153:                         cellView(text: header, column: col, isHeader: true)
154:                     }
155:                 }
156:                 .background(Color(uiColor: .secondarySystemBackground))
157: 
158:                 ForEach(Array(rows.enumerated()), id: \.offset) { rowIndex, row in
159:                     Rectangle()
160:                         .fill(Color(uiColor: .separator).opacity(0.25))
161:                         .frame(height: 0.5)
162:                         .gridCellUnsizedAxes([.horizontal])
163: 
164:                     GridRow {
165:                         ForEach(0..<headers.count, id: \.self) { col in
166:                             let value = col < row.count ? row[col] : ""
167:                             cellView(text: value, column: col, isHeader: false)
168:                         }
169:                     }
170:                     .background(rowIndex.isMultiple(of: 2)
171:                                 ? Color.clear
172:                                 : Color(uiColor: .secondarySystemBackground).opacity(0.35))
173:                 }
174:             }
175:             .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
176:             .overlay {
177:                 RoundedRectangle(cornerRadius: 12, style: .continuous)
178:                     .strokeBorder(Color(uiColor: .separator).opacity(0.25), lineWidth: 0.5)
179:             }
180:         }
181:     }
182: 
183:     @ViewBuilder
184:     private func cellView(text: String, column: Int, isHeader: Bool) -> some View {
185:         let alignment = column < alignments.count ? alignments[column] : .leading
186:         AgentInlineMarkdownText(source: text)
187:             .font(isHeader ? .subheadline.weight(.semibold) : .subheadline)
188:             .foregroundStyle(.primary)
189:             .multilineTextAlignment(textAlignment(for: alignment))
190:             .frame(maxWidth: .infinity, alignment: Alignment(horizontal: alignment, vertical: .center))
191:             .padding(.horizontal, 12)
192:             .padding(.vertical, 9)
193:     }
194: 
195:     private func textAlignment(for alignment: HorizontalAlignment) -> TextAlignment {
196:         switch alignment {
197:         case .center: return .center
198:         case .trailing: return .trailing
199:         default: return .leading
200:         }
201:     }
202: }
