251: struct MarkdownSegment: Identifiable, Equatable {
252:     enum Kind: Equatable {
253:         case prose(String)
254:         case code(language: String, code: String)
255:         case table(headers: [String], alignments: [HorizontalAlignment], rows: [[String]])
256:         case blockquote(String)
257:         case thematicBreak
258:     }
259: 
260:     let id: Int
261:     let kind: Kind
262: 
263:     static func parse(_ source: String) -> [MarkdownSegment] {
264:         let lines = source.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
265:         var segments: [MarkdownSegment] = []
266:         var proseLines: [String] = []
267:         var index = 0
268: 
269:         func flushProse() {
270:             let joined = proseLines.joined(separator: "\n")
271:             if !joined.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
272:                 segments.append(MarkdownSegment(id: segments.count, kind: .prose(joined)))
273:             }
274:             proseLines.removeAll(keepingCapacity: true)
275:         }
276: 
277:         while index < lines.count {
278:             let line = lines[index]
279:             let trimmed = line.trimmingCharacters(in: .whitespaces)
280: 
281:             // 1. 围栏代码块
282:             if trimmed.hasPrefix("```") {
283:                 flushProse()
284:                 let language = String(trimmed.dropFirst(3)).trimmingCharacters(in: .whitespaces)
285:                 var codeLines: [String] = []
286:                 index += 1
287:                 while index < lines.count {
288:                     if lines[index].trimmingCharacters(in: .whitespaces).hasPrefix("```") {
289:                         index += 1
290:                         break
291:                     }
292:                     codeLines.append(lines[index])
293:                     index += 1
294:                 }
295:                 segments.append(MarkdownSegment(
296:                     id: segments.count,
297:                     kind: .code(language: language, code: codeLines.joined(separator: "\n"))
298:                 ))
299:                 continue
300:             }
301: 
302:             // 2. GFM 表格（表头 + 分隔行）
303:             if index + 1 < lines.count,
304:                let headers = parseTableRow(lines[index]),
305:                let alignments = parseTableSeparator(lines[index + 1], expectedColumns: headers.count) {
306:                 flushProse()
307:                 var rows: [[String]] = []
308:                 index += 2
309:                 while index < lines.count {
310:                     let candidate = lines[index].trimmingCharacters(in: .whitespaces)
311:                     if candidate.isEmpty || !candidate.contains("|") {
312:                         break
313:                     }
314:                     if let row = parseTableRow(lines[index]) {
315:                         rows.append(row)
316:                         index += 1
317:                     } else {
318:                         break
319:                     }
320:                 }
321:                 segments.append(MarkdownSegment(
322:                     id: segments.count,
323:                     kind: .table(headers: headers, alignments: alignments, rows: rows)
324:                 ))
325:                 continue
326:             }
327: 
328:             // 3. 引用块
329:             if trimmed.hasPrefix(">") {
330:                 flushProse()
331:                 var quoteLines: [String] = []
332:                 while index < lines.count {
333:                     let quoteTrimmed = lines[index].trimmingCharacters(in: .whitespaces)
334:                     guard quoteTrimmed.hasPrefix(">") else { break }
335:                     var content = String(quoteTrimmed.dropFirst())
336:                     if content.hasPrefix(" ") {
337:                         content = String(content.dropFirst())
338:                     }
339:                     quoteLines.append(content)
340:                     index += 1
341:                 }
342:                 let joined = quoteLines.joined(separator: "\n")
343:                 if !joined.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
344:                     segments.append(MarkdownSegment(id: segments.count, kind: .blockquote(joined)))
345:                 }
346:                 continue
347:             }
348: 
349:             // 4. 分割线
350:             if isThematicBreak(trimmed) {
351:                 flushProse()
352:                 segments.append(MarkdownSegment(id: segments.count, kind: .thematicBreak))
353:                 index += 1
354:                 continue
355:             }
356: 
357:             proseLines.append(line)
358:             index += 1
359:         }
360: 
361:         flushProse()
362:         return segments
363:     }
364: 
365:     private static func isThematicBreak(_ trimmed: String) -> Bool {
366:         guard trimmed.count >= 3 else { return false }
367:         let stripped = trimmed.filter { !$0.isWhitespace }
368:         guard stripped.count >= 3, let first = stripped.first, "-*_".contains(first) else {
369:             return false
370:         }
371:         return stripped.allSatisfy { $0 == first }
372:     }
373: 
374:     private static func parseTableRow(_ raw: String) -> [String]? {
375:         let trimmed = raw.trimmingCharacters(in: .whitespaces)
376:         guard trimmed.contains("|") else { return nil }
377:         var inner = trimmed
378:         if inner.hasPrefix("|") { inner.removeFirst() }
379:         if inner.hasSuffix("|") { inner.removeLast() }
380:         let cells = inner.split(separator: "|", omittingEmptySubsequences: false).map {
381:             $0.trimmingCharacters(in: .whitespaces)
382:         }
383:         return cells.isEmpty ? nil : cells
384:     }
385: 
386:     private static func parseTableSeparator(_ raw: String, expectedColumns: Int) -> [HorizontalAlignment]? {
387:         guard let cells = parseTableRow(raw), cells.count == expectedColumns else { return nil }
388:         var alignments: [HorizontalAlignment] = []
389:         for cell in cells {
390:             guard !cell.isEmpty else { return nil }
391:             let leftColon = cell.hasPrefix(":")
392:             let rightColon = cell.hasSuffix(":")
393:             let middle = cell.dropFirst(leftColon ? 1 : 0).dropLast(rightColon ? 1 : 0)
394:             guard !middle.isEmpty, middle.allSatisfy({ $0 == "-" }) else { return nil }
395:             if leftColon && rightColon {
396:                 alignments.append(.center)
397:             } else if rightColon {
398:                 alignments.append(.trailing)
399:             } else {
400:                 alignments.append(.leading)
401:             }
402:         }
403:         return alignments
404:     }
405: }

