10: /**
11:  * 负责从环境识别与模块优先级组装生成最终 System Prompt 的建造者
12:  */
13: public class PromptBuilder {
14: 
15:     /**
16:      * 运行时环境上下文对象。
17:      *
18:      * @param workDir   当前智能体工作根目录
19:      * @param os        宿主操作系统名称（如 macos, windows 11, linux）
20:      * @param arch      宿主 CPU 架构（如 x86_64, aarch64）
21:      * @param shell     当前使用的终端 Shell 名称（如 bash, zsh, cmd.exe）
22:      * @param isGitRepo 当前工作目录是否处于 Git 仓库中
23:      * @param gitBranch 当前 Git 分支名称（若非 Git 仓库则为空）
24:      * @param model     当前调用的大语言模型标识/名称
25:      * @param date      当前系统 ISO 日期（格式：YYYY-MM-DD）
26:      */
27:     public record EnvironmentContext(
28:             String workDir,
29:             String os,
30:             String arch,
31:             String shell,
32:             boolean isGitRepo,
33:             String gitBranch,
34:             String model,
35:             String date
36:     ) {}
37: 
38:     /** 保存所有已添加的 PromptSection 模块列表 */
39:     public final List<PromptSection> sections = new ArrayList<>();
40: 
41:     public PromptBuilder add(PromptSection section) {
42:         if (section != null) {
43:             sections.add(section);
44:         }
45:         return this;
46:     }
47: 
48:     /**
49:      * 按 Priority 升序排序并用双换行拼接
50:      * @return
51:      */
52:     public String build() {
53:         // 关键：按 Priority 数值从小到大排序（优先级高/数值小的排在最前面）
54:         sections.sort(Comparator.comparingInt(PromptSection::priority));
55: 
56:         ArrayList<String> parts = new ArrayList<>();
57:         for (PromptSection s : sections) {
58:             String content = s.content() == null ? "" : s.content().strip();
59:             if (!content.isEmpty()) {
60:                 parts.add(content);
61:             }
62:         }
63:         // 每个模块间保留双换行，保证 Markdown 标题与段落间距清晰
64:         return String.join("\n\n",parts);
65:     }
66: 
67:     /**
68:      * 自动探测当前宿主机的操作系统、Shell、CPU 架构以及 Git 仓库状态。
69:      *
70:      * @param modelName     当前选用的 LLM 模型名称
71:      * @param customWorkDir 自定义工作目录路径（若传入 null 或空白串，则默认使用当前 JVM 的 user.dir）
72:      * @return 探测填充后的 {@link EnvironmentContext} 环境对象
73:      */
74:     public static EnvironmentContext detectEnvironment(String modelName, String customWorkDir) {
75:         // 1. 解析工作目录
76:         String workDir = customWorkDir != null && !customWorkDir.isBlank()
77:                 ? customWorkDir : System.getProperty("user.dir");
78: 
79:         // 2. 读取操作系统与架构
80:         String os = System.getProperty("os.name", "unknown").toLowerCase();
81:         String arch = System.getProperty("os.arch", "unknown");
82: 
83:         // 3. 读取用户 Shell 环境
84:         String shell = System.getenv("SHELL");
85:         if (shell == null || shell.isEmpty()) {
86:             shell = os.contains("win") ? "cmd.exe" : "bash";
87:         }
88: 
89:         boolean isGitRepo = false;
90:         String gitBranch = "";
91: 
92:         // 4. 探测当前目录是否在 Git 仓库树内部
93:         try {
94:             Process p = new ProcessBuilder("git", "-C", workDir, "rev-parse", "--is-inside-work-tree")
95:                     .redirectErrorStream(true)
96:                     .start();
97:             try (var reader = new BufferedReader(new InputStreamReader(p.getInputStream()))) {
98:                 String line = reader.readLine();
99:                 if ("true".equals(line != null ? line.strip() : "")) {
100:                     isGitRepo = true;
101:                 }
102:             }
103:             p.waitFor();
104:         } catch (Exception ignored) {
105:             // 当系统没有安装 Git 或当前目录非 Git 仓库时捕获异常并静默处理
106:         }
107: 
108:         // 5. 若确认是 Git 仓库，获取当前 HEAD 对应的分支名称
109:         if (isGitRepo) {
110:             try {
111:                 Process p = new ProcessBuilder("git", "-C", workDir, "rev-parse", "--abbrev-ref", "HEAD")
112:                         .redirectErrorStream(true)
113:                         .start();
114:                 try (var reader = new BufferedReader(new InputStreamReader(p.getInputStream()))) {
115:                     String line = reader.readLine();
116:                     if (line != null) {
117:                         gitBranch = line.strip();
118:                     }
119:                 }
120:                 p.waitFor();
121:             } catch (Exception ignored) {
122:                 // 分支检测失败时静默忽略，保持 gitBranch 为空字符串
123:             }
124:         }
125: 
126:         // 6. 获取当前本地 ISO 格式日期（YYYY-MM-DD）
127:         String date = LocalDate.now().toString();
128: 
129:         return new EnvironmentContext(workDir, os, arch, shell, isGitRepo, gitBranch, modelName, date);
130:     }
131: 
132: 
133:     /**
134:      * 构建普通会话（含日常聊天与随后的工程操作）使用的 System Prompt。
135:      *
136:      * @param modelName 当前模型名称
137:      * @param workDir 当前工作目录
138:      * @return 组装后的系统提示词
139:      */
140:     public static String buildDefaultSystemPrompt(String modelName, String workDir) {
141:         EnvironmentContext env = detectEnvironment(modelName, workDir);
142:         return engineeringSections(env)
143:                 .add(PromptsSections.conversationSection())
144:                 .add(PromptsSections.languageSection())
145:                 .add(PromptsSections.judgementSection())
