31:   const trimmed = src.trim();
32:   if (/^(https?:|data:|blob:)/i.test(trimmed)) return trimmed;
33: 
34:   // micromark 会百分号编码链接目标（空格、非 ASCII、反斜杠等），先解码还原真实文件路径
35:   let localPath = trimmed;
36:   try {
