72:       React.isValidElement(child) && child.type === 'code'
73:   );
74:   const language = (codeChild?.props.className || '').match(/language-([\w-]+)/)?.[1] || undefined;
75:   const codeText = codeChild ? extractCodeText(codeChild.props.children) : '';
76:   if (language?.toLowerCase() === 'mermaid') {
77:     return <MermaidBlock code={codeText} />;
78:   }
79:   return <CodeBlock language={language} code={codeText} />;
80: };
81: 
82: /** 表格：外层横向滚动容器，表头吸顶。 */
83: const TableBlock: React.FC<React.ComponentPropsWithoutRef<'table'>> = ({ children, ...props }) => (
84:   <div className={styles.tableWrap}>
85:     <table {...props}>{children}</table>
86:   </div>
87: );
88: 
89: /**
90:  * 容错清洗：修复模型输出中被压缩在同一行的 Markdown 表格。
91:  */
92: function normalizeMarkdown(raw?: string): string {
93:   if (!raw) return '';
94: 
95:   const blocks = raw.split(/(```[\s\S]*?```)/g);
96:   return blocks
97:     .map((block, idx) => {
98:       if (idx % 2 === 1) return block;
99: 
100:       const res = block.replace(/\|\s*\|\s*(?=[^\n]*\|)/g, '|\n|');
101:       const lines = res.split(/\r?\n/);
102:       const output: string[] = [];
103:       let inTable = false;
104: 
105:       for (let i = 0; i < lines.length; i++) {
106:         const line = lines[i];
107:         const trimmed = line.trim();
108:         const isTableLine = trimmed.startsWith('|') && trimmed.endsWith('|');
109: 
110:         if (isTableLine) {
111:           if (!inTable) {
112:             if (output.length > 0 && output[output.length - 1].trim() !== '') {
113:               output.push('');
114:             }
115:             inTable = true;
116:           }
117:           output.push(trimmed);
118:         } else {
119:           if (inTable) {
120:             if (trimmed !== '') {
121:               output.push('');
122:             }
123:             inTable = false;
124:           }
125:           output.push(line);
126:         }
127:       }
128: 
129:       return output.join('\n');
130:     })
131:     .join('');
132: }
133: 
134: export interface MarkdownContentProps {
135:   content?: string;
136:   className?: string;
137: }
138: 
139: /**
140:  * 统一 Markdown 渲染：GFM + 代码语法高亮 + Mermaid 图表。
141:  */
142: export const MarkdownContent: React.FC<MarkdownContentProps> = ({
143:   content,
144:   className = '',
145: }) => {
146:   const [previewSrc, setPreviewSrc] = useState<string | null>(null);
147: 
148:   // 图片预览：Esc 关闭
149:   useEffect(() => {
150:     if (!previewSrc) return;
151:     const onKeyDown = (e: KeyboardEvent) => {
152:       if (e.key === 'Escape') setPreviewSrc(null);
153:     };
154:     window.addEventListener('keydown', onKeyDown);
155:     return () => window.removeEventListener('keydown', onKeyDown);
156:   }, [previewSrc]);
157: 
158:   return (
159:     <div className={`${styles.markdown} ${className}`}>
160:       <ReactMarkdown
161:         remarkPlugins={[remarkGfm]}
162:         urlTransform={(url, key) => {
163:           // 图片 src：放行 file/data/本地盘符等，由 resolveImageSrc 统一处理
164:           if (key === 'src') return url;
165:           // 相对链接直接放行；绝对链接仅保留安全的网络/邮件/电话协议
166:           const scheme = /^([a-z][a-z0-9+.-]*):/i.exec(url);
167:           if (!scheme) return url;
168:           return /^(https?|mailto|tel):/i.test(url) ? url : '';
169:         }}
170:         components={{
171:           pre: PreBlock,
172:           table: TableBlock,
173:           img: (props) => {
174:             const src = resolveImageSrc(props.src || '');
175:             return (
176:               <img
177:                 {...props}
178:                 src={src}
179:                 onClick={() => setPreviewSrc(src)}
180:                 alt={props.alt || '图片'}
181:                 title="点击查看大图"
182:               />
183:             );
184:           },
185:         }}
186:       >
187:         {normalizeMarkdown(content)}
188:       </ReactMarkdown>
189: 
190:       {/* 图片详情预览（Lightbox） */}
191:       {previewSrc &&
192:         createPortal(
193:           <div
194:             className={styles.lightbox}
195:             role="dialog"
196:             aria-modal="true"
197:             aria-label="图片预览"
198:             onClick={() => setPreviewSrc(null)}
199:           >
200:             <img
201:               src={previewSrc}
202:               alt="图片预览"
203:               className={styles.lightboxImg}
204:               onClick={(e) => e.stopPropagation()}
205:             />
206:             <button
207:               type="button"
208:               className={styles.lightboxClose}
209:               onClick={() => setPreviewSrc(null)}
210:               aria-label="关闭预览"
211:               title="关闭预览 (Esc)"
212:             >
213:               <X size={18} />
214:             </button>
215:           </div>,
216:           document.body
217:         )}
218:     </div>
219:   );
220: };

